INSERT INTO `roles` (`id`, `name`, `slug`, `description`, `created_at`) VALUES
('1', 'Super Admin', 'admin', 'Full system control, user management, and school year lock management', '2026-08-22 20:18:18'),
('2', 'Academic Coordinator', 'coordinator', 'Manages DepEd curriculum, subjects, tracks, strands, sections, and faculty loading', '2026-08-22 20:18:18'),
('3', 'Registrar', 'registrar', 'Evaluates & approves requirements, manages enrollment queue, and issues enrollment forms', '2026-08-22 20:18:18'),
('4', 'Treasury', 'treasury', 'Manages fee structures, vouchers, discounts, payments, and issues Official Receipts', '2026-08-22 20:18:18'),
('5', 'School Records Custodian', 'records', 'Maintains permanent student records, SF9, SF10 transcripts, and certifications', '2026-08-22 20:18:18'),
('6', 'Teacher / Faculty', 'teacher', 'Handles subject schedules, attendance, and submits quarterly student grades', '2026-08-22 20:18:18'),
('7', 'Student', 'student', 'Enrolled student with access to schedules, grades, statement of accounts', '2026-08-22 20:18:18'),
('8', 'Applicant', 'applicant', 'Temporary admission account to complete registration and track application status', '2026-08-22 20:18:18'),
('9', 'Master Scheduler', 'scheduler', 'Oversees section class timetables, room assignments, faculty loading, and school event calendar', '2026-08-23 21:00:32');
